module div_8bit(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, output res_ready, output [15:0] result, output res_valid
);
// Your design here
reg res_valid_reg,res_ready_reg;
reg [15:0] result_reg;
reg start_cnt_reg;
reg [3:0] cnt_reg;
reg [8:0] neg_divisor_reg;
reg [7:0] dividend_abs_reg,divisor_abs_reg;
reg [17:0] sr_reg;
wire [17:0] sub_result_wire;
wire [17:0] mux_out_wire;
wire carry_out_wire;
assign sub_result_wire = sr_reg + {9'b0,neg_divisor_reg}; // Adder/Subtractor
assign mux_out_wire = (sub_result_wire[17]) ? sr_reg : sub_result_wire;
assign carry_out_wire = ~sub_result_wire[17];
always @(posedge clk or posedge rst) begin
    if(rst) begin
        res_valid_reg <= 1'b0;
        res_ready_reg <= 1'b0;
        result_reg <= 16'd0;

        start_cnt_reg <= 1'b0;
        cnt_reg <= 4'd0;
        neg_divisor_reg <= 9'd0;
        dividend_abs_reg <= 8'd0;
        divisor_abs_reg <= 8'd0;
        sr_reg <= 18'd0;
    end else begin
        case(cnt_reg)
            4'd0: begin
                if(opn_valid && !res_valid_reg) begin
                    dividend_abs_reg <= (sign & dividend[7]) ? (~dividend+1'b1) : dividend;
                    divisor_abs_reg <= (sign & divisor[7]) ? (~divisor+1'b1) : divisor;
                    neg_divisor_reg <= ~(divisor_abs_reg)+1'b1;

                    sr_reg <= {1'b0,dividend_abs_reg} << 1;
                    cnt_reg <= 4'd1;
                    start_cnt_reg <= 1'b1;
                end
            end

            default: begin
                if(start_cnt_reg) begin
                    if(cnt_reg[3]) begin
                        cnt_reg <= 4'd0;
                        start_cnt_reg <= 1'b0;

                        sr_reg <= mux_out_wire;
                        result_reg <= {sr_reg[17:1],carry_out_wire};
                        res_valid_reg <= 1'b1;
                    end else begin
                        cnt_reg <= cnt_reg + 1'b1;
                        sr_reg <= {mux_out_wire[16:0],carry_out_wire};
                    end
                end
            end
        endcase

        if(res_valid_reg && res_ready_reg) begin
            res_valid_reg <= 1'b0;
        end
    end
end
assign res_valid=res_valid_reg;
assign res_ready=res_ready_reg;
assign result=result_reg;
assign start_cnt=start_cnt_reg;
assign cnt=cnt_reg;
assign neg_divisor=neg_divisor_reg;
assign dividend_abs=dividend_abs_reg;
assign divisor_abs=divisor_abs_reg;
assign sr=sr_reg;
endmodule
